import{_ as d,C as r,o as a,c as s,aj as e,E as n}from"./framework.js";const f=JSON.parse('{"title":"内容条目 | Cms / Content | Documentation","description":"内容条目 in Kooboo: 文件夹：/_Admin/content/textContentsByFolder?SiteId=...&folder=[内容文件夹Id]","frontmatter":{"title":"内容条目 | Cms / Content | Documentation","description":"内容条目 in Kooboo: 文件夹：/_Admin/content/textContentsByFolder?SiteId=...&folder=[内容文件夹Id]","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cms/content/contents-entries.html"}]]},"headers":[],"relativePath":"zh/cms/content/contents-entries.md","filePath":"cms/content/contents-entries.md","lastUpdated":1780282991000}'),c={name:"zh/cms/content/contents-entries.md"};function l(h,t,i,g,m,b){const o=r("DocImage");return a(),s("div",null,[t[0]||(t[0]=e('<h1 id="内容条目" tabindex="-1">内容条目 <a class="header-anchor" href="#内容条目" aria-label="Permalink to &quot;内容条目&quot;">​</a></h1><blockquote><p><strong>文件夹</strong>：<code>/_Admin/content/textContentsByFolder?SiteId=...&amp;folder={内容文件夹Id}</code><br><strong>编辑条目</strong>：<code>/_Admin/content/content?SiteId=...&amp;folder={内容文件夹Id}&amp;id={条目Id}</code>（新建可无 <code>id</code>）<br><strong>单条内容</strong>：列表点名称直接进入 <code>content</code> 路由，仅维护唯一一条</p></blockquote><p>在某一 <a href="./contents-folders-list.html">内容文件夹</a> 下创建、编辑具体数据行。表单字段由该夹的 <a href="./content-types.html">数据类型</a> 决定；若配置了 <a href="./contents-folder-settings.html">关联数据</a>，编辑页会出现对应区块（类别/内嵌选择器）。</p><h2 id="进入方式" tabindex="-1">进入方式 <a class="header-anchor" href="#进入方式" aria-label="Permalink to &quot;进入方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>内容文件夹类型</th><th>操作</th></tr></thead><tbody><tr><td><strong>文件夹</strong></td><td>列表点击内容文件夹 <strong>名称</strong> → 条目列表 → <strong>新建</strong> / 行内编辑</td></tr><tr><td><strong>单条内容</strong></td><td>列表点击 <strong>名称</strong> → 直接进入该条编辑（无列表页）</td></tr></tbody></table>',5)),n(o,{src:"/cms/content/contents-entry.png",alt:"文件夹内条目列表",width:"1120"}),t[1]||(t[1]=e('<h2 id="条目列表-文件夹" tabindex="-1">条目列表（文件夹） <a class="header-anchor" href="#条目列表-文件夹" aria-label="Permalink to &quot;条目列表（文件夹）&quot;">​</a></h2><p>工具栏常见能力：</p><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td><strong>新建 {显示名}</strong></td><td>创建一条新内容</td></tr><tr><td><strong>导出数据</strong> / <strong>导入数据</strong></td><td>CSV 批量导出、导入（以界面为准）</td></tr><tr><td>搜索、筛选</td><td>若数据类型含可用于筛选的字段，顶部可能出现筛选器</td></tr><tr><td>批量删除等</td><td>勾选后操作（权限允许时）</td></tr></tbody></table><p>列表列一般包含标识、摘要字段、在线状态、修改时间等（随数据类型与 <a href="./contents-folder-settings.html#字段">内容文件夹设置 · 字段</a> 顺序而变）。</p><h2 id="编辑页" tabindex="-1">编辑页 <a class="header-anchor" href="#编辑页" aria-label="Permalink to &quot;编辑页&quot;">​</a></h2><p>路由 <code>content</code>，中央为动态表单：</p><ul><li><strong>数据类型字段</strong>：文本、富文本、图片、日期等。</li><li><strong>类别数据</strong>：按 <a href="./contents-folder-settings.html">内容文件夹设置</a> 中配置的别名，从关联夹 <strong>多选/单选</strong> 条目（勾选「多个」时允许多选）。</li><li><strong>内嵌数据</strong>：从关联夹 <strong>挑选要嵌入</strong> 的条目，可排序；分组内嵌在 UI 上分区展示。</li></ul><p>底部栏（<strong>文件夹</strong> 且非单条内容文件夹时常见）：</p><table tabindex="0"><thead><tr><th>按钮</th><th>说明</th></tr></thead><tbody><tr><td>保存</td><td>写入当前条目</td></tr><tr><td>保存并返回</td><td>保存后回到条目列表</td></tr><tr><td>保存并新建</td><td>保存后继续新建下一条（新建时）</td></tr><tr><td>保存并预览</td><td>按预览 URL 打开前台；多语言站点可选语言</td></tr></tbody></table>',9)),n(o,{src:"/cms/content/contents-entry-edit.png",alt:"新建/编辑内容条目",width:"1120"}),t[2]||(t[2]=e('<p><strong>单条内容</strong> 夹通常只有 <strong>保存</strong> / <strong>取消</strong>，无「保存并新建」等列表相关按钮。</p><h2 id="在线与多语言" tabindex="-1">在线与多语言 <a class="header-anchor" href="#在线与多语言" aria-label="Permalink to &quot;在线与多语言&quot;">​</a></h2><ul><li>条目是否 <strong>在线</strong>、按语言下线等，以表单与站点多语言设置为准。</li><li>多语言字段在 <a href="./content-types.html">数据类型</a> 中启用 <strong>启用多语言</strong> 后，编辑页可按语言切换录入。</li></ul><h2 id="保存后如何用-k-content" tabindex="-1">保存后如何用 k.content <a class="header-anchor" href="#保存后如何用-k-content" aria-label="Permalink to &quot;保存后如何用 k.content&quot;">​</a></h2><table tabindex="0"><thead><tr><th>内容文件夹类型</th><th>读取方式</th></tr></thead><tbody><tr><td>文件夹</td><td><code>k.content.{夹名}.all()</code>、<code>get(id)</code>、<code>find(...)</code> 等</td></tr><tr><td>单条内容</td><td><code>k.content.{夹名}.字段Name</code> 直接访问</td></tr><tr><td>关联数据</td><td>在 <code>get</code> 到的条目上通过 <a href="./contents-folder-settings.html#在-kcontent-中读取关联数据">别名</a> 访问</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="./contents-folders-list.html">内容列表</a></td><td>文件夹 vs 单条内容</td></tr><tr><td><a href="./contents-folder-settings.html">内容设置</a></td><td>关联与字段顺序</td></tr><tr><td><a href="/kb-docs/zh/api/content/">k.content</a></td><td>CRUD、查询运算符</td></tr><tr><td><a href="/kb-docs/zh/templateEngine/k-data/query.html">k-data</a></td><td>模板列表绑定</td></tr></tbody></table>',7))])}const p=d(c,[["render",l]]);export{f as __pageData,p as default};
